cat > /tmp/rename.py << 'PYEOF'
import re, os, sys

DRY = '--apply' not in sys.argv
OLD, NEW = 'disableTooltip', 'hideHint'
PILL_TAGS = {'app-pill', 'app-fancy-pill', 'app-status-pill'}
report = []

def tag_attr_spans(text):
    """Yield (tagname, attr_start, attr_end) for every element tag, skipping comments."""
    i, n = 0, len(text)
    while i < n:
        c = text.find('<', i)
        if c == -1:
            return
        if text.startswith('<!--', c):
            e = text.find('-->', c)
            i = e + 3 if e != -1 else n
            continue
        m = re.match(r'</?([a-zA-Z][\w-]*)', text[c:])
        if not m:
            i = c + 1
            continue
        j = c + m.end()
        while j < n:
            ch = text[j]
            if ch in '"\'':
                q = text.find(ch, j + 1)
                j = q + 1 if q != -1 else n
                continue
            if ch == '>':
                break
            j += 1
        yield m.group(1), c + m.end(), min(j, n)
        i = min(j, n) + 1

def unquoted_chunks(s):
    """Yield (text, is_quoted) chunks of an attribute area."""
    i, n = 0, len(s)
    buf = ''
    while i < n:
        ch = s[i]
        if ch in '"\'':
            if buf:
                yield buf, False
                buf = ''
            q = s.find(ch, i + 1)
            end = q + 1 if q != -1 else n
            yield s[i:end], True
            i = end
            continue
        buf += ch
        i += 1
    if buf:
        yield buf, False

def transform_template(text, path, offset_line=0):
    pill_refs = set()
    for name, a, b in tag_attr_spans(text):
        if name in PILL_TAGS:
            for chunk, quoted in unquoted_chunks(text[a:b]):
                if not quoted:
                    pill_refs.update(re.findall(r'#([\w$]+)', chunk))
    out, pos, changes = [], 0, 0
    for name, a, b in tag_attr_spans(text):
        if name not in PILL_TAGS:
            continue
        area = text[a:b]
        if OLD not in area:
            continue
        new_area = ''
        for chunk, quoted in unquoted_chunks(area):
            if quoted:
                new_area += chunk
            else:
                new_area += chunk.replace(OLD, NEW)
                changes += chunk.count(OLD)
        out.append(text[pos:a]); out.append(new_area); pos = b
    out.append(text[pos:])
    text = ''.join(out)
    for ref in sorted(pill_refs):
        pat = re.compile(r'\b' + re.escape(ref) + r'\.' + OLD + r'\b')
        text, k = pat.subn(ref + '.' + NEW, text)
        changes += k
    return text, changes

def inline_template_regions(text):
    regions = []
    for m in re.finditer(r'template\s*:\s*`', text):
        s = m.end()
        e = text.index('`', s)
        regions.append((s, e))
    return regions

LIB_FULL = {'pill.component.ts', 'fancy-pill.component.ts', 'status-pill.component.ts'}
TS_CODE_PAT = re.compile(r'\b(this\.(?:fancy|firstPill|pills)\(\)\??\.|fancy\.|pill\.)' + OLD + r'\b')

def process_ts(path):
    text = open(path, encoding='utf-8').read()
    orig = text
    base = os.path.basename(path)
    total = 0
    if base in LIB_FULL:
        text, n = text, text.count(OLD)
        text = orig.replace(OLD, NEW)
        total += n
    else:
        # inline templates
        regions = inline_template_regions(text)
        pieces, pos = [], 0
        for s, e in regions:
            body, n = transform_template(text[s:e], path)
            pieces.append(text[pos:s]); pieces.append(body); pos = e
            total += n
        pieces.append(text[pos:])
        text = ''.join(pieces)
        # ts code outside templates
        regions = inline_template_regions(text)
        pieces, pos = [], 0
        for s, e in regions:
            pieces.append(TS_CODE_PAT.sub(lambda m: m.group(1) + NEW, text[pos:s]))
            pieces.append(text[s:e]); pos = e
        tail, k = TS_CODE_PAT.subn(lambda m: m.group(1) + NEW, text[pos:])
        pieces.append(tail)
        text = ''.join(pieces)
        total += sum(1 for _ in TS_CODE_PAT.finditer(orig))  # approx count
    if text != orig:
        report.append((path, total))
        if not DRY:
            open(path, 'w', encoding='utf-8', newline='').write(text)

def process_html(path):
    text = open(path, encoding='utf-8').read()
    new, n = transform_template(text, path)
    if new != text:
        report.append((path, n))
        if not DRY:
            open(path, 'w', encoding='utf-8', newline='').write(new)

for root, dirs, files in os.walk('src'):
    for fn in sorted(files):
        p = os.path.join(root, fn)
        if fn.endswith('.ts'):
            process_ts(p)
        elif fn.endswith('.html'):
