TS_CODE_PAT = re.compile(r'\b(this\.(?:fancy|firstPill|pills)\(\)\??\.|fancy\.|pill\.)' + OLD + r'\b')

def process_ts(path):
    text = open(path, encoding='utf-8').read()
    orig = text
    base = os.path.basename(path)
    total = 0
    if base in LIB_FULL:
        text, n = text, text.count(OLD)
        text = orig.replace(OLD, NEW)
        total += n
    else:
